package com.clinic.notification.service;
import com.clinic.notification.domain.*;import com.clinic.notification.dto.NotificationDtos.*;import com.clinic.notification.repository.*;import com.fasterxml.jackson.databind.ObjectMapper;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service public class NotificationQueueService{
 private final JobRepository jobs;private final MedicationPlanRepository plans;private final ObjectMapper mapper;public NotificationQueueService(JobRepository jobs,MedicationPlanRepository plans,ObjectMapper mapper){this.jobs=jobs;this.plans=plans;this.mapper=mapper;}
 @Transactional public void enqueue(EventRequest e){try{String json=mapper.writeValueAsString(e);add(e.eventId()+":EMAIL:PATIENT",NotificationJob.Channel.EMAIL,e.type(),e.patientId(),e.patientEmail(),e.appointmentId(),json);add(e.eventId()+":EMAIL:DOCTOR",NotificationJob.Channel.EMAIL,e.type(),e.doctorUserId(),e.doctorEmail(),e.appointmentId(),json);String action=switch(e.type()){case"BOOKING_CONFIRMED"->"CREATE";case"APPOINTMENT_RESCHEDULED"->"UPDATE";case"APPOINTMENT_CANCELLED","DOCTOR_LEAVE_CANCELLED"->"DELETE";default->null;};if(action!=null){add(e.eventId()+":CAL:PATIENT",NotificationJob.Channel.CALENDAR,action,e.patientId(),e.patientEmail(),e.appointmentId(),json);add(e.eventId()+":CAL:DOCTOR",NotificationJob.Channel.CALENDAR,action,e.doctorUserId(),e.doctorEmail(),e.appointmentId(),json);}}catch(Exception x){throw new IllegalArgumentException("Invalid notification payload",x);}}
 @Transactional public void addPlan(MedicationPlanRequest r){if(r.endAt().isBefore(r.startAt()))throw new IllegalArgumentException("Medication endAt must follow startAt");if(!plans.existsByDedupeKey(r.eventId()))plans.save(new MedicationPlan(r.eventId(),r.userId(),r.email(),r.appointmentId(),r.medication(),r.instructions(),r.intervalHours(),r.startAt(),r.endAt()));}
 private void add(String key,NotificationJob.Channel c,String action,UUID user,String email,UUID appointment,String json){if(!jobs.existsByDedupeKey(key))jobs.save(new NotificationJob(key,c,action,user,email,appointment,json));}
}
